#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: prepare one Ubuntu 22.04 Compute Engine host for the GPU demo.
# Re-running is safe: every stage detects work that is already complete.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

# The shared wizard palette includes RED for wizards that need it.
: "$RED"

script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
repo_root="$(cd "$script_dir/../.." && pwd)"
front_root="${TCC_FRONT_REPO:-$(cd "$repo_root/.." && pwd)/tcc-front}"

banner "Prepare the GCP GPU demo host"

stage "Confirm the VM"
say "This wizard expects a fresh Ubuntu 22.04 LTS VM in southamerica-east1."
open_url "https://console.cloud.google.com/compute/instances"
step "Confirm machine type n1-standard-4 and one NVIDIA T4 GPU."
step "Confirm a boot disk of at least 50 GB and an ephemeral external IPv4 address."
step "Confirm Secure Boot is off, OS Login is enabled, and HTTP/HTTPS firewall boxes are off."
step "Confirm SSH ingress is restricted to IAP: 35.235.240.0/20 on tcp:22."
if ! confirm "Does this VM match every item above?"; then
  warn "Correct the VM configuration before preparing the host."
  exit 1
fi

stage "Install the NVIDIA driver"
if command -v nvidia-smi >/dev/null 2>&1 && nvidia-smi >/dev/null 2>&1; then
  say "The NVIDIA driver is already working; skipping installation."
else
  if ! command -v curl >/dev/null 2>&1 || ! command -v python3 >/dev/null 2>&1; then
    if confirm "Install curl and Python 3 with apt?"; then
      sudo apt-get update
      sudo apt-get install -y curl python3
    else
      warn "curl and Python 3 are required by the official Compute Engine installer."
      exit 1
    fi
  fi

  installer_dir="${XDG_CACHE_HOME:-$HOME/.cache}/tcc-gpu-demo"
  installer_path="$installer_dir/cuda_installer.pyz"
  mkdir -p "$installer_dir"
  if [[ ! -s "$installer_path" ]]; then
    say "Downloading Google's current Compute Engine GPU installer."
    curl -fL \
      https://storage.googleapis.com/compute-gpu-installation-us/installer/latest/cuda_installer.pyz \
      --output "$installer_path"
  else
    say "The Compute Engine GPU installer is already cached."
  fi

  if confirm "Install the production NVIDIA driver from the official repository?"; then
    sudo python3 "$installer_path" install_driver \
      --installation-mode=repo \
      --installation-branch=prod
  else
    warn "The GPU driver is required before Docker can use the T4."
    exit 1
  fi

  if ! nvidia-smi >/dev/null 2>&1; then
    warn "A reboot is required. Reconnect by IAP and run this wizard again afterward."
    if confirm "Reboot the VM now?"; then
      sudo reboot
    fi
    exit 0
  fi
fi

stage "Install Docker Engine and Compose"
docker_ready=false
if command -v docker >/dev/null 2>&1 && docker compose version >/dev/null 2>&1; then
  docker_ready=true
fi

host_tools_ready=true
for command_name in curl git jq openssl; do
  command -v "$command_name" >/dev/null 2>&1 || host_tools_ready=false
done

if [[ "$docker_ready" == true && "$host_tools_ready" == true ]]; then
  say "Docker Engine, Compose v2, and the host tools are already installed."
else
  if confirm "Install Docker Engine, Compose v2, and host tools from official apt repositories?"; then
    sudo apt-get update
    sudo apt-get install -y ca-certificates curl git jq openssl
    sudo install -m 0755 -d /etc/apt/keyrings
    sudo curl -fsSL https://download.docker.com/linux/ubuntu/gpg \
      -o /etc/apt/keyrings/docker.asc
    sudo chmod a+r /etc/apt/keyrings/docker.asc
    # shellcheck disable=SC1091
    ubuntu_codename="$(. /etc/os-release && echo "${UBUNTU_CODENAME:-$VERSION_CODENAME}")"
    architecture="$(dpkg --print-architecture)"
    printf '%s\n' \
      'Types: deb' \
      'URIs: https://download.docker.com/linux/ubuntu' \
      "Suites: $ubuntu_codename" \
      'Components: stable' \
      "Architectures: $architecture" \
      'Signed-By: /etc/apt/keyrings/docker.asc' | \
      sudo tee /etc/apt/sources.list.d/docker.sources >/dev/null
    sudo apt-get update
    sudo apt-get install -y \
      docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin
  else
    warn "Docker Engine and Compose v2 are required by the demo stack."
    exit 1
  fi
fi

stage "Install the NVIDIA Container Toolkit"
toolkit_ready=false
if command -v nvidia-ctk >/dev/null 2>&1; then
  toolkit_ready=true
fi

if [[ "$toolkit_ready" == true ]]; then
  say "The NVIDIA Container Toolkit is already installed."
else
  if confirm "Install NVIDIA Container Toolkit 1.20.1 from NVIDIA's apt repository?"; then
    sudo apt-get update
    sudo apt-get install -y --no-install-recommends ca-certificates curl gnupg2
    curl -fsSL https://nvidia.github.io/libnvidia-container/gpgkey | \
      sudo gpg --dearmor --yes \
        -o /usr/share/keyrings/nvidia-container-toolkit-keyring.gpg
    curl -sL https://nvidia.github.io/libnvidia-container/stable/deb/nvidia-container-toolkit.list | \
      sed 's#deb https://#deb [signed-by=/usr/share/keyrings/nvidia-container-toolkit-keyring.gpg] https://#g' | \
      sudo tee /etc/apt/sources.list.d/nvidia-container-toolkit.list >/dev/null
    sudo apt-get update
    toolkit_version="1.20.1-1"
    sudo apt-get install -y \
      "nvidia-container-toolkit=$toolkit_version" \
      "nvidia-container-toolkit-base=$toolkit_version" \
      "libnvidia-container-tools=$toolkit_version" \
      "libnvidia-container1=$toolkit_version"
  else
    warn "The NVIDIA Container Toolkit is required for GPU containers."
    exit 1
  fi
fi

runtime_configured=false
if [[ -r /etc/docker/daemon.json ]] && grep -q 'nvidia-container-runtime' /etc/docker/daemon.json; then
  runtime_configured=true
fi

if [[ "$runtime_configured" == true ]]; then
  say "Docker is already configured with the NVIDIA runtime."
else
  if confirm "Configure Docker to use the NVIDIA runtime?"; then
    sudo nvidia-ctk runtime configure --runtime=docker
  else
    warn "Docker cannot expose the T4 until its NVIDIA runtime is configured."
    exit 1
  fi
  if confirm "Restart Docker now to activate the NVIDIA runtime?"; then
    sudo systemctl restart docker
  else
    warn "Restart Docker and rerun this wizard before starting the demo."
    exit 1
  fi
fi

stage "Validate repositories and Docker access"
if [[ ! -f "$repo_root/package.json" || ! -d "$repo_root/gesture-server" ]]; then
  warn "The backend repository is incomplete: $repo_root"
  exit 1
fi
if [[ ! -f "$front_root/package.json" ]]; then
  warn "Clone tcc-front beside tcc-back, or set TCC_FRONT_REPO to its absolute path."
  note "Expected frontend repository: $front_root"
  exit 1
fi
say "Found sibling repositories:"
note "backend:  $repo_root"
note "frontend: $front_root"

if id -nG "$USER" | tr ' ' '\n' | grep -qx docker; then
  say "The current user already belongs to the docker group."
else
  warn "Docker group membership grants root-equivalent access on this host."
  if confirm "Add $USER to the docker group?"; then
    sudo usermod -aG docker "$USER"
    warn "Reconnect through IAP so the new group membership takes effect, then rerun this wizard."
    exit 0
  else
    warn "Add the user manually or run every Docker command with sudo."
    exit 1
  fi
fi

stage "Validate the GPU container stack"
step "Checking the host driver with nvidia-smi."
nvidia-smi
step "Checking the T4 inside the same CUDA base used by the worker."
docker run --rm --gpus all nvidia/cuda:13.0.0-base-ubuntu22.04 nvidia-smi
step "Resolving the Compose model with non-secret placeholder values."
COMPOSE_PROJECT_NAME=tcc-gcp-config-check \
IMAGE_TAG=config-check \
POSTGRES_USER=tcc \
POSTGRES_DB=cattle_auction_demo \
POSTGRES_PASSWORD=config-check-only \
DATABASE_URL=postgresql://tcc:config-check-only@postgres:5432/cattle_auction_demo \
JWT_SECRET=config-check-only \
FRONTEND_URL=https://config-check.invalid \
DEMO_PASSWORD=config-check-only \
GESTURE_TOKEN=config-check-only \
GESTURE_ALLOWED_ORIGINS=https://config-check.invalid \
TCC_FRONT_CONTEXT="$front_root" \
TCC_GATEWAY_DOCKERFILE="$repo_root/deploy/gcp/gateway.Dockerfile" \
docker compose -f "$repo_root/deploy/gcp/compose.yaml" config --quiet

say "Host validation passed. Start the demo from the backend repository:"
note "cd $repo_root"
note "./scripts/gcp-demo/start.sh"
note "./scripts/gcp-demo/status.sh"

finish
